-- Study plan import for my-study-planner / Supabase
-- Batch: study-plan-h2-2026-v1
-- Date range: 2026-06-23 to 2026-12-31
-- IMPORTANT: Replace PUT-YOUR-USER-ID-HERE with your Supabase auth.users.id.
-- You can find your user id in Supabase Dashboard > Authentication > Users.

DO $$
DECLARE
  v_user_id uuid := 'PUT-YOUR-USER-ID-HERE'::uuid;
BEGIN
  DELETE FROM tasks WHERE user_id = v_user_id AND note LIKE '%batch_id=study-plan-h2-2026-v1%';
  DELETE FROM goals WHERE user_id = v_user_id AND title LIKE '[H2-2026]%';


END $$;